## Using the right tRPC client
Make sure you use the right tRPC client.
When using tRPC in React, you generally wrap the client in
`react-query`.
tRPC Chat Agents uses the raw tRPC client instead.
`import type { AppRouter } from '@/server/trpc';`
import { httpBatchLink, splitLink, unstable_httpSubscriptionLink } from '@trpc/client';
import { createTRPCReact } from '@trpc/react-query';
// Use this for react
export const trpc = createTRPCReact<AppRouter>();
// Use this for for tRPC Chat Agent
export const trpcClient = trpc.createClient({
links: [
splitLink({
// uses the httpSubscriptionLink for subscriptions
condition: (op) => op.type === 'subscription',
true: unstable_httpSubscriptionLink({
url: `/api/trpc`,
}),
false: httpBatchLink({
url: `/api/trpc`,
}),
}),
],
});

