import { initTRPC } from '@trpc/server';
import * as trpcExpress from '@trpc/server/adapters/express';
import express from 'express';
import cors from 'cors';

const t = initTRPC.create();

const appRouter = t.router({
  countdown: t.procedure.subscription(async function* () {
    for (let i = 5; i >= 1; i--) {
      yield i;
      await new Promise((resolve) => setTimeout(resolve, 100));
    }
  }),
});

export type AppRouter = typeof appRouter;

const app = express();
app.use(cors());

app.use(
  '/trpc',
  trpcExpress.createExpressMiddleware({
    router: appRouter,
  })
);

const PORT = 3000;
app.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});

import { createTRPCClient, httpSubscriptionLink } from '@trpc/client';
import type { AppRouter } from './server';
import EventSource from 'eventsource';
import * as fs from 'fs';

const client = createTRPCClient<AppRouter>({
  links: [
    httpSubscriptionLink({
      url: 'http://localhost:3000/trpc',
      EventSource: EventSource as any,
    }),
  ],
});

const results: number[] = [];

console.log('Subscribing to countdown...');

const subscription = client.countdown.subscribe(undefined, {
  onData(data) {
    console.log('Received data:', data);
    results.push(data);
  },
  onError(err) {
    console.error('Subscription error:', err);
    fs.writeFileSync(
      '/home/user/project/output.json',
      JSON.stringify(results)
    );
    process.exit(1);
  },
  onComplete() {
    console.log('Subscription completed. Writing results...');
    fs.writeFileSync(
      '/home/user/project/output.json',
      JSON.stringify(results)
    );
    console.log('Done!');
    subscription.unsubscribe();
    process.exit(0);
  },
});

