import { createTRPCClient, httpSubscriptionLink } from '@trpc/client';
import type { AppRouter } from './server';
import EventSource from 'eventsource';

const client = createTRPCClient<AppRouter>({
  links: [
    httpSubscriptionLink({
      url: 'http://localhost:3000/trpc',
      EventSource: EventSource as any,
    }),
  ],
});

client.countdown.subscribe(undefined, {
  onData(data) {
    console.log('Data:', data);
  },
  onError(err: any) {
    console.log('Error name:', err.name);
    console.log('Error message:', err.message);
    if (err.cause) {
      console.log('Cause name:', err.cause.name);
      console.log('Cause message:', err.cause.message);
      console.log('Cause error:', err.cause.error);
      console.log('Cause suppressed:', err.cause.suppressed);
      if (err.cause.error) {
        console.log('Cause error stack:', err.cause.error.stack);
      }
      if (err.cause.suppressed) {
        console.log('Cause suppressed stack:', err.cause.suppressed.stack);
      }
    }
    process.exit(1);
  },
});

